var t=254;var a=[{id:`cooking-254-01`,theoryId:254,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why are potatoes and quinoa useful study ingredients in Andean culinary traditions?`,ua:`Чому картопля та кіноа важливі для вивчення андських кулінарних традицій?`},explanation:{en:`Andean cuisines feature diverse tubers, grains and preservation traditions.`,ua:`Андські кухні охоплюють різні бульбоплоди, зернові та способи збереження.`},options:[{id:`a`,text:{en:`They illustrate regional staples and their adaptation to local conditions`,ua:`Вони демонструють місцеві основні продукти та їхню адаптацію до умов регіону`}},{id:`b`,text:{en:`They require identical cooking techniques in every dish`,ua:`Вони потребують однакових методів у кожній страві`}},{id:`c`,text:{en:`They are the only ingredients eaten in South America`,ua:`Це єдині продукти, які споживають у Південній Америці`}}],answer:{optionIds:[`a`]}},{id:`cooking-254-02`,theoryId:254,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`All South American culinary cultures use the same ingredients and historical methods.`,ua:`Усі південноамериканські кулінарні культури використовують однакові інгредієнти та історичні методи.`},explanation:{en:`Foodways differ across the Andes, Amazon, coasts and other regions.`,ua:`Кулінарні традиції різняться між Андами, Амазонією, узбережжями та іншими регіонами.`},answer:{value:!1}},{id:`cooking-254-03`,theoryId:254,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match regional staples with preparation characteristics.`,ua:`Поєднайте регіональні продукти з особливостями приготування.`},explanation:{en:`Food preservation and variety selection shape regional preparations.`,ua:`Консервування та вибір сорту визначають регіональні страви.`},leftItems:[{id:`l1`,text:{en:`Quinoa`,ua:`Кіноа`}},{id:`l2`,text:{en:`Potato`,ua:`Картопля`}},{id:`l3`,text:{en:`Chuño`,ua:`Чуньйо`}}],rightItems:[{id:`r2`,text:{en:`Tuber with varieties suited to different textures`,ua:`Бульба, сорти якої підходять для різних текстур`}},{id:`r3`,text:{en:`Traditional freeze-dried potato product`,ua:`Традиційний висушений морозом картопляний продукт`}},{id:`r1`,text:{en:`Small seed cooked as a grain`,ua:`Дрібне насіння, яке готують як крупу`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-254-04`,theoryId:254,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`You are adapting a traditional quinoa dish for a new kitchen. What should you verify first?`,ua:`Ви адаптуєте традиційну страву з кіноа для нової кухні. Що варто перевірити насамперед?`},explanation:{en:`Product state and variety influence absorption and final texture.`,ua:`Стан продукту та сорт впливають на поглинання рідини й кінцеву текстуру.`},options:[{id:`a`,text:{en:`Add no water because quinoa is always pre-cooked`,ua:`Не додавати води, адже кіноа завжди попередньо зварена`}},{id:`b`,text:{en:`Assume every quinoa variety needs identical water`,ua:`Припустити, що всі сорти кіноа потребують однакової кількості води`}},{id:`c`,text:{en:`Check the ingredient specification, rinse if appropriate, and test hydration`,ua:`Перевірити характеристики продукту, за потреби промити й випробувати гідратацію`}}],answer:{optionIds:[`c`]}},{id:`cooking-254-05`,theoryId:254,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which features may matter when comparing Andean and broader South American cooking?`,ua:`Що варто враховувати при порівнянні андської та ширшої південноамериканської кухні?`},explanation:{en:`Geography and community history explain much of the variety.`,ua:`Географія та історія громад пояснюють значну частину різноманітності.`},options:[{id:`a`,text:{en:`Local tuber varieties`,ua:`Місцеві сорти бульбоплодів`}},{id:`b`,text:{en:`A claim of one uniform continental recipe`,ua:`Твердження про один єдиний рецепт для всього континенту`}},{id:`c`,text:{en:`Preserved ingredients and altitude adaptations`,ua:`Консервовані продукти й адаптації до високогір’я`}},{id:`d`,text:{en:`Regional differences in grains and seafood`,ua:`Регіональні відмінності круп і морепродуктів`}}],answer:{optionIds:[`a`,`c`,`d`]}}];var n={theoryId:254,exercises:a};export{n as default,a as exercises,t as theoryId};